                        XState.put (latest', accepted ++ buffer ++ [ch])
                        loop1 p [] str
        runFast :: [((Int, Int), Char)] -> XIdentity.Identity ((Maybe Int, [((Int, Int), Char)]), [((Int, Int), Char)])
        runFast input = do
            (rest, (latest, accepted)) <- XState.runStateT (loop1 q0 [] input) (Nothing, [])
            return ((latest, accepted), rest)
    addLoc :: Int -> Int -> String -> [((Int, Int), Char)]
    addLoc _ _ [] = []
    addLoc row col (ch : chs) = if ch == '\n' then ((row, col), ch) : addLoc (row + 1) 1 chs else ((row, col), ch) : addLoc row (col + 1) chs
    runAladdinLexerRaw_this :: [((Int, Int), Char)] -> Either (Int, Int) [Either (Int, Int) Token]
    runAladdinLexerRaw_this [] = return []
    runAladdinLexerRaw_this str0 = do
        let return_one my_token = return [my_token]
        dfa_output <- runDFA theDFA str0
        (str1, piece) <- case dfa_output of
            ((_, []), _) -> Left (fst (head str0))
            ((Just label, accepted), rest) -> return (rest, ((label, map snd accepted), (fst (head accepted), fst (head (reverse accepted)))))
            _ -> Left (fst (head str0))
        tokens1 <- case piece of
            ((1, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_dot (SLoc (row1, col1) (row2, col2))))
            ((2, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arrow (SLoc (row1, col1) (row2, col2))))
            ((3, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_fatarrow (SLoc (row1, col1) (row2, col2))))
            ((4, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_lparen (SLoc (row1, col1) (row2, col2))))
            ((5, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_rparen (SLoc (row1, col1) (row2, col2))))
            ((6, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_lbracket (SLoc (row1, col1) (row2, col2))))
            ((7, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_rbracket (SLoc (row1, col1) (row2, col2))))
            ((8, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_quest (SLoc (row1, col1) (row2, col2))))
            ((9, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_comma (SLoc (row1, col1) (row2, col2))))
            ((10, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_fatarrow (SLoc (row1, col1) (row2, col2))))
            ((11, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_if (SLoc (row1, col1) (row2, col2))))
            ((12, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_Eq (SLoc (row1, col1) (row2, col2))))
            ((13, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Is))
            ((14, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Eq))
            ((15, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Ne))
            ((16, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Lt))
            ((17, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Le))
            ((18, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Gt))
            ((19, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_arithmetic_predicate (SLoc (row1, col1) (row2, col2)) AP_Ge))
            ((20, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_plus (SLoc (row1, col1) (row2, col2))))
            ((21, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_minus (SLoc (row1, col1) (row2, col2))))
            ((22, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_star (SLoc (row1, col1) (row2, col2))))
            ((23, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_slash (SLoc (row1, col1) (row2, col2))))
            ((24, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_quotient (SLoc (row1, col1) (row2, col2))))
            ((25, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_div (SLoc (row1, col1) (row2, col2))))
            ((26, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_mod (SLoc (row1, col1) (row2, col2))))
            ((27, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_rem (SLoc (row1, col1) (row2, col2))))
            ((28, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_succ (SLoc (row1, col1) (row2, col2))))
            ((29, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_pi (SLoc (row1, col1) (row2, col2))))
            ((30, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_sigma (SLoc (row1, col1) (row2, col2))))
            ((31, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_semicolon (SLoc (row1, col1) (row2, col2))))
            ((32, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_cut (SLoc (row1, col1) (row2, col2))))
            ((33, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_true (SLoc (row1, col1) (row2, col2))))
            ((34, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_fail (SLoc (row1, col1) (row2, col2))))
            ((35, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_debug (SLoc (row1, col1) (row2, col2))))
            ((36, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_bslash (SLoc (row1, col1) (row2, col2))))
            ((37, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_cons (SLoc (row1, col1) (row2, col2))))
            ((38, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_kind (SLoc (row1, col1) (row2, col2))))
            ((39, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_type (SLoc (row1, col1) (row2, col2))))
            ((40, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_smallid (SLoc (row1, col1) (row2, col2)) this))
            ((41, this), ((row1, col1), (row2, col2))) -> return_one (Right (T_largeid (SLoc (row1, col1) (row2, col2)) this))
            ((42, this), ((row1, col1), (row2, col2))) -> return_one (readLiteralToken (row1, col1) (T_nat_lit (SLoc (row1, col1) (row2, col2))) this)
            ((43, this), ((row1, col1), (row2, col2))) -> return_one (readLiteralToken (row1, col1) (T_str_lit (SLoc (row1, col1) (row2, col2))) this)
            ((44, this), ((row1, col1), (row2, col2))) -> return_one (readLiteralToken (row1, col1) (T_chr_lit (SLoc (row1, col1) (row2, col2))) this)
            ((45, this), ((row1, col1), (row2, col2))) -> return []
            ((46, this), ((row1, col1), (row2, col2))) -> return []
            ((47, this), ((row1, col1), (row2, col2))) -> return []
        tokens2 <- runAladdinLexerRaw_this str1
        return (tokens1 ++ tokens2)
